// kompot-navigation

export interface NavigationGraph {
  routes: ScreenRoute[];
}

export interface ScreenRoute {
  /** Matches the string a server puts into navigate.deeplink */
  deeplink: string;
  /** The relative address the screen is fetched from. Its endpoint kind MUST equal this route's kind */
  endpoint: string;
  title?: string | null;
  /** What stands behind the endpoint, in the vocabulary of x-kompot-endpoint-kind: "screen" yields a KompotComponent, "form" a KompotFormResponse. Absent means "screen". An open string rather than an enum on purpose: a client MUST ignore a route whose kind it does not recognise, and an unknown enum constant would fail the parse of the whole graph before one route could be skipped */
  kind?: string;
  /** How the route's screen is shown: "screen" (pushed, the default), "sheet" or "dialog" (laid over the screen it was opened from). An open string: a client MUST show a route whose presentation it does not recognise or cannot draw as a screen, never hide it */
  presentation?: string;
}

