// kompot-theme

export interface KompotPalette {
  /** ColorToken key -> colour. The value is a hex string (#RGB, #RRGGBB or #AARRGGBB, with or without the hash); alpha defaults to opaque. A malformed value is treated as an absent one — the client keeps its built-in colour */
  colors?: Record<string, string>;
}

export interface KompotTextStyle {
  fontSizeSp?: number | null;
  lineHeightSp?: number | null;
  fontWeight?: number | null;
  letterSpacingSp?: number | null;
  color?: string | null;
}

export interface KompotTheme {
  id: string;
  light?: KompotPalette;
  /** Absent means the brand described no dark theme. A client MUST then stay entirely on its built-in dark palette rather than substituting the light one */
  dark?: KompotPalette | null;
  /** TypographyToken key -> style. One set for both themes. Every property of a style is optional: what is absent keeps the client's built-in value */
  typography?: Record<string, KompotTextStyle>;
}

