// Hierarchies — every variant the build's profile lists

export type FieldValue = FieldValueAmountValue | FieldValueBooleanValue | FieldValueEntityValue | FieldValueTextValue | UnknownFieldValue;

/** A FieldValue this build does not know — the protocol promises it may arrive (SPEC.md §2.1). */
export interface UnknownFieldValue {
  type: string;
  [property: string]: unknown;
}

export type FormCondition = FormConditionEquals | FormConditionNotEquals | UnknownFormCondition;

/** A FormCondition this build does not know — the protocol promises it may arrive (SPEC.md §2.1). */
export interface UnknownFormCondition {
  type: string;
  [property: string]: unknown;
}

export type FormFieldDefinition = FormFieldDefinitionAmountField | FormFieldDefinitionAutocompleteField | FormFieldDefinitionCheckboxField | FormFieldDefinitionSelectionField | FormFieldDefinitionTextField | UnknownFormFieldDefinition;

/** A FormFieldDefinition this build does not know — the protocol promises it may arrive (SPEC.md §2.1). */
export interface UnknownFormFieldDefinition {
  type: string;
  /** Unique within a FormSchema; ties the definition to the UI component that refers to it */
  fieldId: string;
  rules?: ValidationRule[];
  /** Evaluated by the client locally, with no round trip to the server */
  visibleIf?: FormCondition | null;
  /** Changing the value requires asking the server for a patch */
  triggersPatch?: boolean;
  [property: string]: unknown;
}

export type KompotAction = KompotActionClose | KompotActionConfirm | KompotActionCopyText | KompotActionLoadPage | KompotActionNavigate | KompotActionOpenUrl | KompotActionPerform | KompotActionPresent | KompotActionRefresh | KompotActionSequence | KompotActionShowMessage | KompotActionSubmitForm | KompotActionUpdateSession | KompotActionWizardBack | KompotActionWizardFinish | KompotActionWizardNext | KompotActionWizardStepResult | UnknownKompotAction;

/** A KompotAction this build does not know — the protocol promises it may arrive (SPEC.md §2.1). */
export interface UnknownKompotAction {
  type: string;
  [property: string]: unknown;
}

export type KompotComponent = KompotComponentAmountInput | KompotComponentAutocompleteInput | KompotComponentBox | KompotComponentButton | KompotComponentCheckboxInput | KompotComponentColumn | KompotComponentDivider | KompotComponentExpandable | KompotComponentImage | KompotComponentPaginatedList | KompotComponentRadioGroup | KompotComponentReadOnlyField | KompotComponentRow | KompotComponentSelectInput | KompotComponentSpacer | KompotComponentTable | KompotComponentTabs | KompotComponentText | KompotComponentTextInput | KompotComponentWizardScreen | UnknownKompotComponent;

/** A KompotComponent this build does not know — the protocol promises it may arrive (SPEC.md §2.1). */
export interface UnknownKompotComponent {
  type: string;
  /** Unique within one screen tree: point updates are addressed by it (see UpdateComponentMessage in :kompot-realtime) */
  id: string;
  /** The order of nodes matters — they are applied left to right */
  modifiers?: KompotModifierNode[];
  /** The equivalent for a reader that does not know this type (SPEC.md §2.1). A reader that knows the type ignores it */
  fallback?: KompotComponent;
  [property: string]: unknown;
}

export type ValidationRule = ValidationRuleMaxAmountFromField | ValidationRuleRegex | ValidationRuleRequired | ValidationRuleRequiredIf | UnknownValidationRule;

/** A ValidationRule this build does not know — the protocol promises it may arrive (SPEC.md §2.1). */
export interface UnknownValidationRule {
  type: string;
  /** Ready localised error text, not a translation key */
  errorMessage: string;
  [property: string]: unknown;
}
